  float rad = vRadius;
  float ang = vAngle;
  #define sat clamp01
const float zoom = q8*uAspect.y, T = q6,speed=q7,  trails = 24,
                   BPMtime=q10, vb=q11, zz=q13;
const vec2 pos = vec2 (q15,q16);
sampler sampler_pw_noise_lq;
{ return abs(max(abs(uvi.x),abs(uvi.y))-0.03);
return abs(length(uvi)-0.01);}
float mask = 0, fog=0, trail = 0;
  vec2 uv1 = (uv_orig-0.5)*uAspect.xy + pos;
  vec2 p, q = multiply(uv1, mat2(_qa))/zoom, t=0, uvt;
  vec3 S = 0, C = vec3(1, 2, 3), col, scr, scm;
  for (int i = 0; i < trails; i++)
  {
    float j=i/trails;
    p = q* (1-zz*j);
    p+= 0.03* sin(pow(i+1.,vec2(17,23)/371)*T)*vec2(1,3);
